B.QF=new A.Z(58504,"MaterialIcons",null,!1)
B.Ps=new A.aX("artificial_social_proof","Artificial Social Proof","Sites falsely claim that 'X people are looking at this right now' to simulate high demand and pressure you.","E-Commerce / Travel Booking","Ignore pop-ups about what other people are doing; evaluate the purchase strictly on your own needs.",B.e0,B.QF,"",null,!1)
B.Rl=new A.Z(62291,"MaterialIcons",null,!1)
B.P0=new A.aX("decoy_pricing","The Decoy Effect","Companies introduce a slightly inferior product at nearly the same price as the premium tier to make the premium tier look like a massive steal.","Huber, Payne, and Puto (1982)","Identify the base tier you actually need and ignore the 'value' comparisons designed to upsell you.",B.c2,B.Rl,"",null,!1)
B.QK=new A.Z(58609,"MaterialIcons",null,!1)
